package com.example.notification.tenant;
import jakarta.validation.constraints.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/tenants") @PreAuthorize("hasRole('PLATFORM_ADMIN')") public class TenantController{private final TenantService service; public TenantController(TenantService s){service=s;} public record Create(@NotBlank String name,@Min(1) @Max(100000) int rateLimitPerSecond){} public record Update(@Min(1) @Max(100000) int rateLimitPerSecond,TenantStatus status){} @PostMapping public Tenant create(@RequestBody @jakarta.validation.Valid Create r){return service.create(r.name(),r.rateLimitPerSecond());}@GetMapping public List<Tenant> list(){return service.list();}@GetMapping("/{id}") public Tenant get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}") public Tenant update(@PathVariable UUID id,@RequestBody @jakarta.validation.Valid Update r){return service.update(id,r.rateLimitPerSecond(),r.status());}}
